import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { IDopIDRepository } from '@src/domain/interfaces/card_dop/dopID';
import { DopIDDataReq } from '@src/domain/entities/card_dop/dopID';

export class DopIDHandler {
    private readonly _repository: IDopIDRepository;

    constructor(
        @inject(TYPES.IDopIDRepository)
        dopIDRepository: IDopIDRepository
    ) {
        this._repository = dopIDRepository;
    }

    handle(query: Query<CardDOPBaseRequest<DopIDDataReq>>, apiType: string) {
        return this._repository.dopID(query, apiType);
    }
}
