import { createSlice } from '@reduxjs/toolkit';
import { fetchConfirmCardInfo, fetchAddCardInfo, fetchCustomerInfoV2 } from '../thunk';
import type { IAddressType } from '../type';

export interface IStateCardSlice {
    status: 'idle' | 'loading' | 'succeeded' | 'failed';
    error: string;
    addressTypeList: IAddressType[];
    addressType: IAddressType;
    addrDetail: string;

    provinceId: string;
    provinceName: string;
    districtId: string;
    districtName: string;
    wardId: string;
    wardName: string;

    dataPayload: {
        email: string;
        ref1MobilePhone: string;
        ref2MobilePhone: string;
        companyName: string;
        companyAddress: string;
        income: string;
        licensePlate: string;
        licensePlateType: string;
        ePassReferralCode: string;
    };
    queue: Record<string, string>;
}

const initialState: IStateCardSlice = {
    status: 'idle',
    error: '',
    addressTypeList: [
        { type: '01', name: 'Địa chỉ liên hệ' },
        { type: '02', name: 'Nơi làm việc' },
        { type: '03', name: 'Khác' }, //Nơi thường trú
    ],
    addressType: { type: '', name: '' },
    addrDetail: '',
    provinceId: '',
    provinceName: '',
    districtId: '',
    districtName: '',
    wardId: '',
    wardName: '',

    dataPayload: {
        email: '',
        ref1MobilePhone: '',
        ref2MobilePhone: '',
        companyName: '',
        companyAddress: '',
        income: '',
        licensePlate: '',
        licensePlateType: '',
        ePassReferralCode: '',
    },
    queue: {},
};

const cardSlice = createSlice({
    name: 'loan_collateral_amount',
    initialState,
    reducers: {
        setError: (state, { payload }) => {
            state.error = payload;
        },
        setStatus: (state, { payload }) => {
            state.status = payload;
        },
        setProvince: (state, { payload }) => {
            state.provinceId = payload?.provinceId;
            state.provinceName = payload?.provinceName;
        },
        setDistrict: (state, { payload }) => {
            state.districtId = payload?.districtId;
            state.districtName = payload?.districtName;
        },
        setWard: (state, { payload }) => {
            state.wardId = payload?.wardId;
            state.wardName = payload?.wardName;
        },
        setDataPayload: (state, { payload }) => {
            state.dataPayload = {
                ...state.dataPayload,
                ...payload,
            };
        },
        setAddressType: (state, { payload }) => {
            state.addressType = payload;
        },
        setAddrDetail: (state, { payload }) => {
            state.addrDetail = payload;
        },
    },
    extraReducers: (builder) => {
        builder
            // ----------------------------------------------------------------
            // fetchCustomerInfoV2 step 1
            // ----------------------------------------------------------------
            .addCase(fetchCustomerInfoV2.pending, (state) => {
                state.status = 'loading';
                state.error = '';
                state.queue.fetchCustomerInfoV2 = 'fetchCustomerInfoV2';
            })
            .addCase(fetchCustomerInfoV2.rejected, (state, action) => {
                delete state.queue.fetchCustomerInfoV2;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'failed';
                }
                state.error = action.error.message ?? 'Failed to fetch fetchCustomerInfoV2';
            })
            .addCase(fetchCustomerInfoV2.fulfilled, (state, action) => {
                delete state.queue.fetchCustomerInfoV2;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'succeeded';
                }
                if (!action?.payload) {
                    state.error = 'Failed to fetch fetchCustomerInfoV2 because of payload undefined';
                    return;
                }
                state.error = '';
                console.log('fetchCustomerInfoV2 payload payload', action);
                const { data, resultCode, resultMessage } = action?.payload;
                if (resultCode === '00' && data) {
                    //
                    console.log('fetchCustomerInfoV2 data', data);
                } else {
                    state.error = resultMessage;
                }
            })
            // ----------------------------------------------------------------
            // fetchAddCardInfo step 2
            // ----------------------------------------------------------------
            .addCase(fetchAddCardInfo.pending, (state) => {
                state.status = 'loading';
                state.error = '';
                state.queue.fetchAddCardInfo = 'fetchAddCardInfo';
            })
            .addCase(fetchAddCardInfo.rejected, (state, action) => {
                delete state.queue.fetchAddCardInfo;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'failed';
                }

                state.error = action.error.message ?? 'Failed to fetch fetchAddCardInfo';
            })
            .addCase(fetchAddCardInfo.fulfilled, (state, { payload }) => {
                delete state.queue.fetchAddCardInfo;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'succeeded';
                }
                if (!payload) {
                    state.error = 'Failed to fetch fetchAddCardInfo because of payload undefined';
                    return;
                }
                state.error = '';
                const { data, resultCode, resultMessage } = payload;
                if (resultCode === '00' && data) {
                    console.log('fetchAddCardInfo data', data);
                } else {
                    state.error = resultMessage;
                }
            })
            // ----------------------------------------------------------------
            // fetchConfirmCardInfo
            // ----------------------------------------------------------------
            .addCase(fetchConfirmCardInfo.pending, (state) => {
                state.status = 'loading';
                state.error = '';
                state.queue.fetchConfirmCardInfo = 'fetchConfirmCardInfo';
            })
            .addCase(fetchConfirmCardInfo.rejected, (state, action) => {
                delete state.queue.fetchConfirmCardInfo;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'failed';
                }
                state.error = action.error.message ?? 'Failed to fetch fetchConfirmCardInfo';
            })
            .addCase(fetchConfirmCardInfo.fulfilled, (state, { payload }) => {
                delete state.queue.fetchConfirmCardInfo;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'succeeded';
                }
                if (!payload) {
                    state.error = 'Failed to fetch fetchConfirmCardInfo because of payload undefined';
                    return;
                }
                state.error = '';
                const { data, resultCode, resultMessage } = payload;
                if (resultCode === '00' && data) {
                    console.log('fetchConfirmCardInfo data', data);
                    //
                } else {
                    state.error = resultMessage;
                }
            });
    },
});

export default cardSlice;
