import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { ICustomerInfoV2Repository } from '@src/domain/interfaces/card_dop/customerInfoV2';
import { CustomerInfoV2DataReq, CustomerInfoV2DataRes } from '@src/domain/entities/card_dop/customerInfoV2';

@injectable()
export class CustomerInfoV2Repository
    extends HttpService
    implements ICustomerInfoV2Repository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async customerInfoV2<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<CustomerInfoV2DataRes>> {
        const request = query.query as unknown as CustomerInfoV2DataReq;
        const url = '/dop-customer-info-v2';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })                
        console.log('\x1b[31m thieuvq3 response customer: ', response);
        return response.data as CardDOPBaseResponse<CustomerInfoV2DataRes>;
    }
}
