import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { ICustomerInfoV2Repository } from '@src/domain/interfaces/card_dop/customerInfoV2';
import { CustomerInfoV2DataReq } from '@src/domain/entities/card_dop/customerInfoV2';

export class CustomerInfoV2Handler {
    private readonly _repository: ICustomerInfoV2Repository;

    constructor(
        @inject(TYPES.ICustomerInfoV2Repository)
        customerInfoV2Repository: ICustomerInfoV2Repository
    ) {
        this._repository = customerInfoV2Repository;
    }

    handle(query: Query<CardDOPBaseRequest<CustomerInfoV2DataReq>>) {
        return this._repository.customerInfoV2(query);
    }
}
