import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import {Query} from '@src/domain/models/query';
import { CardDOPBaseRequest } from '@src/domain/entities/common/cardDOPBaseApi';
import type { IRegisterUserRepository } from '@src/domain/interfaces/card_dop/registerUser';
import { RegisterUserDataReq } from '@src/domain/entities/card_dop/registerUser';

export class RegisterUserHandler {
    private readonly _repository: IRegisterUserRepository;

    constructor(
        @inject(TYPES.IRegisterUserRepository)
        registerUserRepository: IRegisterUserRepository
    ) {
        this._repository = registerUserRepository;
    }

    handle(query: Query<CardDOPBaseRequest<RegisterUserDataReq>>) {
        return this._repository.registerUser(query);
    }
}
