import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { DopIDDataReq, DopIDDataRes } from '@src/domain/entities/card_dop/dopID';
import { IDopIDRepository } from '@src/domain/interfaces/card_dop/dopID';
import { OCR_FACE, OCR_ID, OCR_NFC } from '@src/utils/constants';

@injectable()
export class DopIDRepository
    extends HttpService
    implements IDopIDRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async dopID<TParameter>(query: Query<TParameter>, apiType: string): Promise<CardDOPBaseResponse<DopIDDataRes>> {
        const request = query.query as unknown as DopIDDataReq;        
        let url = '';
        console.log('\x1b[31m thieuvq3 apiType: ', apiType);
        switch(apiType){
            case OCR_ID: url = '/dop-ids'; break;
            case OCR_FACE: url = '/dop-face'; break;
            case OCR_NFC: url = '/dop-nfc'; break;
            default: break;
        }
        console.log('\x1b[31m thieuvq3 url: ', url);
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })        
        console.log('\x1b[31m thieuvq3 response: ', response);
        return response.data as CardDOPBaseResponse<DopIDDataRes>;
    }
}
