import React from 'react';
import { Text, Pressable, StyleProp, TextStyle } from 'react-native';
import { Trans } from 'react-i18next';
import useCss from '@src/presentation/style';

interface Props {
    text: string;
    style?: StyleProp<TextStyle>;
    onPress?: () => void; // Thêm prop để xử lý sự kiện nhấn vào highlight
}

const TnCText: React.FC<Props> = ({ text, style, onPress }) => {
    const css = useCss();

    return (
        <Text style={[style]}>
            <Trans
                defaults={text}
                components={{
                    highlighted: <Text onPress={onPress} style={[css.text_red_600, css.font_bold, css.underline]} />,
                }}
            />
        </Text>
    );
};

export default TnCText;
