import React, { useEffect, useState } from 'react';
import { SafeAreaView, ScrollView, View, ImageBackground } from 'react-native';
import { GradientButton, LoadingBlockerView, DynamicHeader, Spacer, Text, createStyles, useTheme } from '@core/ui';
import useCSS from '@src/presentation/style';
import { useNavigation } from '@react-navigation/native';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { useTranslation } from 'react-i18next';
import { HDBankLogoDash } from '@src/assets/images/icons';
import PasswordInput from '../components/passwordInput';
import Ratio from '../components/ratio/Ratio';
import { encryptPasswordRSA, formatPublicKeyPEM } from '@src/utils/common';
import { fetchRegisterUser } from './thunk';
import { CardDOPBaseRequest, CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { RegisterUserDataReq, RegisterUserDataRes } from '@src/domain/entities/card_dop/registerUser';
import { useDispatch, useSelector } from '@src/lib/redux';
import { selectRegisterStatus, selectStatus } from './redux/selector';
import { selectValidateOCRRes } from '../redux/selector';
import { selectLeadId, selectPhone } from '../dop_cvp/redux/CVPSelector';

interface IPasswordRequirements {
    id: string;
    label: string;
    pattern?: any;
}

const DOPPasswordScreen = () => {
    const dispatch = useDispatch();
    const { theme } = useTheme();
    const styles = useStyles();
    const css = useCSS();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { t } = useTranslation(['module_dop']);

    const status = useSelector(selectStatus);
    const registerStatus = useSelector(selectRegisterStatus);
    const validateOCRRes = useSelector(selectValidateOCRRes);
    const leadId = useSelector(selectLeadId)
    const phoneNumber = useSelector(selectPhone)

    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [disabled, setDisabled] = useState(true);

    const passwordRequirements = [
        { id: 'length', pattern: '', label: t('screen_password.minimum_characters') },
        { id: 'lowerUpperCase', pattern: /(?=.*[a-z])(?=.*[A-Z])/g, label: t('screen_password.upper_lower_case') },
        { id: 'number', pattern: /[0-9]/g, label: t('screen_password.include_number') },
        { id: 'specialCharacter', pattern: /(?=.*[@.#$!%*?&])/g, label: t('screen_password.special_characters') },
    ];

    useEffect(() => {
        let arr = new Array(4).fill(false);
        passwordRequirements.forEach((item, index) => {
            arr[index] = getChecked(item);
        });
        const isValid = arr[0] && arr[1] && arr[2] && arr[3] && password === confirmPassword;
        setDisabled(!isValid);
    }, [password, confirmPassword]);

    useEffect(() => {
        if (registerStatus) {
            navigation.navigate('dop_pin_screen');
        }
    }, [registerStatus]);

    const getChecked = (item: IPasswordRequirements) => {
        switch (item.id) {
            case 'length':
                return password?.length >= 8;
            case 'lowerUpperCase':
            case 'number':
            case 'specialCharacter':
                return password ? item.pattern?.test?.(password) : false;

            default:
                return false;
        }
    };

    const handleSubmit = () => {
        if (disabled) {
            return;
        }
        const apiPublicKey = validateOCRRes?.data?.publicKey || '';
        const pass = encryptPasswordRSA(password, formatPublicKeyPEM(apiPublicKey));
        dispatch(fetchRegisterUser({ leadId: leadId || '', password: pass } as CardDOPBaseRequest<RegisterUserDataReq>['data'])).then((res) => {
            if ((res.payload as CardDOPBaseResponse<RegisterUserDataRes>)?.resultCode === '00') {
                navigation.navigate('dop_pin_screen');
            }
        });
    };

    return (
        <ImageBackground source={require('@src/assets/images/bg_body.jpg')} resizeMode='cover' style={[css.flex_1]}>
            <SafeAreaView style={[css.flex_1]}>
                <DynamicHeader
                    onBackPress={() => {
                        navigation.goBack();
                    }}
                    MainComponent={() => (
                        <View style={styles.mainContainer}>
                            <HDBankLogoDash style={styles.mainLogo} />
                        </View>
                    )}
                />
                {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
                <ScrollView showsHorizontalScrollIndicator={false} showsVerticalScrollIndicator={false}>
                    <View style={[css.flex_1, css.mt_xLarge, css.mh_medium]}>
                        <Text style={[css.text_title_200, css.font_semibold, css.text_black]}>
                            {t('screen_password.create')}{' '}
                            <Text style={[css.text_title_200, css.font_semibold, css.text_red_600]}>{t('screen_password.pass_online_banking')}</Text>{' '}
                            {t('screen_password.your')}
                        </Text>
                        <Spacer height={24} />
                        <Text style={[css.text_subheadline, css.font_medium, css.text_neutral_700]}>{t('screen_password.username')}</Text>
                        <Text style={[css.text_body, css.font_medium, css.text_black]}>{phoneNumber}</Text>
                        <Spacer height={24} />
                        <PasswordInput label={t('screen_password.password')} value={password} onChangeText={setPassword} style={css.mv_base} />
                        <Spacer height={16} />
                        <PasswordInput
                            label={t('screen_password.confirm_password')}
                            value={confirmPassword}
                            onChangeText={setConfirmPassword}
                            style={css.mv_base}
                        />
                        <Spacer height={24} />
                        <Text style={[css.text_subheadline, css.font_medium, css.text_black]}>{t('screen_password.password_require')}:</Text>
                        <Spacer height={12} />
                        {passwordRequirements.map((item, index) => {
                            return (
                                <Ratio
                                    key={index}
                                    label={item.label}
                                    onChange={() => undefined}
                                    checked={getChecked(item)}
                                    textStyle={[css.text_subheadline, css.text_black]}
                                    containerStyle={css.mv_small}
                                    dotStyle={{ width: 16, height: 16 }}
                                    isDotIcon={false}
                                    activeColor={theme.Colors.Background.Success}
                                />
                            );
                        })}
                    </View>
                    <View style={[css.mt_auto, css.p_medium]}>
                        <GradientButton
                            title={t('screen_password.confirm')}
                            gradientProps={disabled ? { type: 'secondary' } : { type: 'primary' }}
                            onPress={handleSubmit}
                        />
                    </View>
                </ScrollView>
            </SafeAreaView>
        </ImageBackground>
    );
};

export default DOPPasswordScreen;

const useStyles = createStyles((theme) => ({
    mainContainer: {
        flex: 1,
        alignItems: 'center',
        justifyContent: 'center',
        gap: theme.Size.Horizontal.Regular,
        height: theme.Size.Vertical.xxxLarge,
    },
    mainLogo: {
        height: theme.Size.Vertical.xxxLarge,
    },
}));
