import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_CARD_DOP_API } from '@src/config';
import { CardDOPBaseResponse } from '@src/domain/entities/common/cardDOPBaseApi';
import { commonService } from '@src/infrastructure/network/networkService';
import { IGetAuthPublicKeyRepository } from '@src/domain/interfaces/card_dop/getAuthPublicKey';
import { GetAuthPublicKeyDataReq, GetAuthPublicKeyDataRes } from '@src/domain/entities/card_dop/getAuthPublicKey';
import { IAuthUserRepository } from '@src/domain/interfaces/card_dop/authUser';
import { AuthUserDataReq, AuthUserDataRes } from '@src/domain/entities/card_dop/authUser';

@injectable()
export class AuthUserRepository
    extends HttpService
    implements IAuthUserRepository {
    constructor() {
        super({ baseURL: BASE_URL_CARD_DOP_API });
    }

    async authUser<TParameter>(query: Query<TParameter>): Promise<CardDOPBaseResponse<AuthUserDataRes>> {
        const request = query.query as unknown as AuthUserDataReq;
        const url = '/auth-user';
        const response = await this.post(url, request, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-dop-mobile' }),
        })                
        console.log('\x1b[31m thieuvq3 response auth-user: ', response);
        return response.data as CardDOPBaseResponse<AuthUserDataRes>;
    }
}
