import React, { FC, useEffect, useState } from 'react';
import { ActionButton, GradientButton, MaterialTextInput, Text } from '@core/ui';
import { View } from 'react-native';
import useCSS from '@src/presentation/style';
import { validator } from '@src/utils/validator';
import { useTranslation } from 'react-i18next';

interface Props {
    onSubmit: (text: string) => void;
}
const ContentPhone: FC<Props> = ({ onSubmit }) => {
    const css = useCSS();
    const [phone, setPhone] = useState('');
    const [valid, setValid] = useState(false);
    const [errorMessage, setErrorMessage] = useState<string | undefined>('');
    const { t } = useTranslation(['validator']);
    const { t: t2 } = useTranslation(['common']);

    const handleChange = (text: string) => {
        const validate = validator.validatePhoneNumber(text);
        setPhone(text);
        console.log('valiate', validate);
        if (!validate.isInvalid) {
            setValid(true);
            setErrorMessage('');
        } else {
            setValid(false);
            setErrorMessage(validate.errors);
        }
    };
    const handleSubmit = (phone: string) => {
        onSubmit?.(phone);
    };
    useEffect(() => {
        if (valid) {
        }
    }, [valid]);
    return (
        <>
            <MaterialTextInput label={t2('phone_number')} keyboardType='number-pad' value={phone} onChangeText={handleChange} maxLength={10} />
            <Text style={[css.text_caption_100, css.text_red_600, css.h_medium]}>{t(`${errorMessage}`)}</Text>
            <View style={[css.mv_medium]}>
                {valid ? (
                    <GradientButton title={t2('continue')} gradientProps={{ type: 'primary' }} onPress={() => handleSubmit(phone)} />
                ) : (
                    <ActionButton title={t2('continue')} type='secondary' state='disabled' />
                )}
            </View>
        </>
    );
};

export default ContentPhone;
