export const fetchConfirmCardInfo = createAsyncThunk('confirmCardInfo/fetch', async (payload: CardDOPBaseRequest<ConfirmCardInfoDataReq>['data']) => {
    const confirmCardInfo = container.get<ConfirmCardInfoHandler>(TYPES.ConfirmCardInfoHandler);
    const payloadReq = commonService.getPayload<CardDOPBaseRequest<ConfirmCardInfoDataReq>, CardDOPBaseRequest<ConfirmCardInfoDataReq>['data']>({ data: payload })
    const query = new Query<CardDOPBaseRequest<ConfirmCardInfoDataReq>>({
        query: {
            ...payloadReq,
            screenName: "MFE-DOP-TnCScreen",
        },
    });
    return await confirmCardInfo.handle(query);
});

